542	    /// The type of each symbol of a component's props, in order: those asked about before in this snapshot from what
543	    /// the checker answered then, shared, and the others in one request. Only the props' own symbols go through it: a
544	    /// component lists most of an earlier one's, while the members of the types inside a prop rarely repeat.
545	    pub(crate) async fn types_of_symbols(&self, symbols: &[&SymbolRef]) -> Result<Vec<Arc<TypeInfo>>, CallError> {
546	        let mut types: Vec<Option<Arc<TypeInfo>>> = {
547	            let known = self.state.symbol_types.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
548	            symbols.iter().map(|symbol| known.by_symbol.get(symbol.text()).cloned()).collect()
549	        };
550	        let unknown: Vec<&SymbolRef> =
551	            symbols.iter().zip(&types).filter(|(_, known)| known.is_none()).map(|(symbol, _)| *symbol).collect();
552	        if !unknown.is_empty() {
553	            let answered = self.rpc.types_of_symbols(&unknown).await?;
554	            if answered.len() != unknown.len() {
555	                return Err(CallError::Rejected(format!(
556	                    "getTypesOfSymbols answered {} types for {} symbols",
557	                    answered.len(),
558	                    unknown.len()
559	                )));
560	            }
561	            let mut known = self.state.symbol_types.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
562	            let mut answered = answered.into_iter();
563	            for (symbol, slot) in symbols.iter().zip(&mut types) {
564	                if slot.is_none()
565	                    && let Some(info) = answered.next()
566	                {
567	                    let shared = known.by_id.entry(info.id).or_insert_with(|| Arc::new(info)).clone();
568	                    known.by_symbol.insert(Box::from(symbol.text()), shared.clone());
569	                    *slot = Some(shared);
570	                }
571	            }
572	        }
573	        Ok(types.into_iter().flatten().collect())
574	    }
