/// The size budget holds no type under 256 KiB of JSON: no type takes fewer bytes than [`MIN_TYPE_BYTES`], so a type
/// of more than [`MAX_SIZE`] types takes more than 256 KiB.
#[test]
fn no_type_under_256_kib_of_json_passes_the_size_budget() {
    let leaves = [
        PropType::String,
        PropType::Number,
        PropType::Boolean,
        PropType::Null,
        PropType::Undefined,
        PropType::Any,
        PropType::Never,
        PropType::Unknown,
        PropType::Void,
        PropType::BigInt,
        PropType::ReactNode,
        PropType::CssProperties,
        PropType::ElementType,
        PropType::SxProps,
    ];
    let smallest = leaves.iter().map(|leaf| serde_json::to_string(leaf).unwrap().len()).min();
    assert_eq!(smallest, Some(MIN_TYPE_BYTES));
    assert!((MAX_SIZE + 1) * MIN_TYPE_BYTES > 256 * 1024);

    // The smallest type past the budget: an array of `any` that many deep is more than 256 KiB.
    let mut nested = PropType::Any;
    for _ in 0..MAX_SIZE {
        nested = PropType::Array(Box::new(nested));
    }
    assert!(past_size_budget(&nested, MAX_SIZE));
    assert!(serde_json::to_string(&nested).unwrap().len() > 256 * 1024);
}

