"""Usage: cuts404a.py out.json — props whose type the size cut replaced: a `truncated`/`depth` type at the top of a prop
(the depth cap starts five levels down, so a top-level depth cut is the size cut), and every `truncated`/`depth` node
less than five levels down, counted by text."""
import collections
import json
import sys

doc = json.load(open(sys.argv[1], 'rb'))


def walk(value, depth, found):
    if isinstance(value, dict):
        if value.get('kind') == 'truncated' and (value.get('limit') or {}).get('type') == 'depth':
            found.append((depth, value.get('text')))
        inner = depth + (1 if value.get('kind') in ('object', 'union', 'intersection') else 0)
        for item in value.values():
            walk(item, inner, found)
    elif isinstance(value, list):
        for item in value:
            walk(item, depth, found)


def props_of(doc):
    """(where, name, type) for every prop: the interned table and the components' own."""
    table = doc.get('props')
    if isinstance(table, dict):
        items = table.items()
    elif isinstance(table, list):
        items = enumerate(table)
    else:
        items = []
    for key, prop in items:
        if isinstance(prop, dict):
            yield key, prop.get('name', key), prop.get('type') or prop.get('propType')


top = collections.Counter()
shallow = collections.Counter()
total = 0
for key, name, ty in props_of(doc):
    total += 1
    if ty is None:
        continue
    if ty.get('kind') == 'truncated' and (ty.get('limit') or {}).get('type') == 'depth':
        top[f"{name}: {ty.get('text')}"] += 1
    found = []
    walk(ty, 0, found)
    for depth, text in found:
        if depth < 5:
            shallow[text] += 1
print('props in table', total, 'keys', list(doc.keys())[:8])
print('props cut at the top', sum(top.values()), 'distinct', len(top))
for name, count in top.most_common(10):
    print('  ', count, name)
print('depth cuts above the depth cap (size cuts), by text', sum(shallow.values()))
for text, count in shallow.most_common(10):
    print('  ', count, text)

